Given the root of a Binary Search Tree (BST) and an integer key, insert a new node with value key into the BST. Return the root of the modified tree after the insertion.Note:  All the nodes have distinct values in the BST and the new value to be inserted is not present in the BST.Example:Input: root = [2, 1, 3], key = 4 Output: [2, 1, 3, N, N, N, 4]Explanation: After inserting the node 4, the new tree will be [2, 1, 3, N, N, N, 4]. Input: root = [2, 1, 3, N, N, N, 6], key = 4 Output: [2, 1, 3, N, N, N, 4, N, 6]Explanation: After inserting the node 4, the new tree will be [2, 1, 3, N, N, N, 4, N, 6]. Try It YourselfTable of Content[Naive Approach] Recursive Insertion - O(h) Time and O(h) Space[Expected Approach] Iterative Traversal - O(h) Time and O(1) Space[Naive Approach] Recursive Insertion - O(h) Time and O(h) SpaceThe idea is to insert the new key at a position that preserves the Binary Search Tree (BST) property. Starting from the root, compare the key with the current node. If the key is smaller, move to the left child; otherwise, move to the right child. Continue this process until a NULL child is reached, then insert the new node at that position as a leaf node. This ensures that the BST property remains valid after the insertion.
            C++

    #include <iostream>
#include <queue>
#include <vector>
using namespace std;

// Structure for a Binary Search Tree node
class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

// Insert a node into the BST
Node* insert(Node* root, int key) {

    // If tree is empty, create a new node
    if (root == nullptr) {
        return new Node(key);
    }

    // Insert into the left subtree
    if (key < root->data) {
        root->left = insert(root->left, key);
    }

    // Insert into the right subtree
    else {
        root->right = insert(root->right, key);
    }

    return root;
}

// Print the tree in level order
void printTree(Node* root) {
    if (root == nullptr) {
        cout << "[]";
        return;
    }

    vector<string> ans;
    queue<Node*> q;
    q.push(root);

    while (!q.empty()) {
        Node* curr = q.front();
        q.pop();

        if (curr == nullptr) {
            ans.push_back("N");
        } else {
            ans.push_back(to_string(curr->data));
            q.push(curr->left);
            q.push(curr->right);
        }
    }

    // Remove trailing N's
    while (!ans.empty() && ans.back() == "N") {
        ans.pop_back();
    }

    cout << "[";
    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i];
        if (i + 1 < ans.size()) {
            cout << ", ";
        }
    }
    cout << "]";
}

int main() {

    // Create the BST
    //        22
    //       /  \
    //     12    30
    //    /  \
    //   8    20
    //          \
    //           21

    Node* root = new Node(22);
    root->left = new Node(12);
    root->right = new Node(30);
    root->left->left = new Node(8);
    root->left->right = new Node(20);
    root->left->right->right = new Node(21);

    int key = 15;

    root = insert(root, key);

    printTree(root);

    return 0;
}


