    // Structure for a Binary Search Tree node
class Node {
    constructor(x) {
        this.data = x;
        this.left = null;
        this.right = null;
    }
}

// Insert a node into the BST
function insert(root, key) {
    let temp = new Node(key);

    // If tree is empty
    if (root === null) {
        return temp;
    }

    // Find the node who is going to
    // have the new node as its child
    let curr = root;
    while (curr !== null) {
        if (curr.data > key && curr.left !== null) {
            curr = curr.left;
        } else if (curr.data < key && curr.right !== null) {
            curr = curr.right;
        } else {
            break;
        }
    }

    // If key is smaller, make it left
    // child, else right child
    if (curr.data > key) {
        curr.left = temp;
    } else {
        curr.right = temp;
    }

    return root;
}

// Print the tree in level order
function printTree(root) {
    if (root === null) {
        console.log("[]");
        return;
    }

    const ans = [];
    const q = [root];

    while (q.length > 0) {
        const curr = q.shift();

        if (curr === null) {
            ans.push("N");
        } else {
            ans.push(curr.data.toString());
            q.push(curr.left);
            q.push(curr.right);
        }
    }

    // Remove trailing N's
    while (ans.length > 0 && ans[ans.length - 1] === "N") {
        ans.pop();
    }

    console.log("[" + ans.join(", ") + "]");
}

